INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES
('101', 'Realização de ações de sensibilização dirigidas à população presente nas instalações, em qualquer momento, quanto as medidas de autoproteção a adotar em caso de ocorrência, ou iminência de ocorrência, de um qualquer dos riscos referidos, ou de outros que se venham a aferir como críticos para a salvaguarda de pessoas e bens, bem como assegurar-se a realização periódica de simulacros, tendo em linha de conta os principais riscos identificados, com o envolvimento dos Agentes de Proteção Civil e dos Serviços Municipais de Proteção Civil.', 'DO', 12, 141),
('102', 'Promover a utilização do transporte coletivo em detrimento do transporte individualizado, no sentido de reduzir o número de veículos rodoviários em circulação.', 'DO', 12, 142),
('103', 'Promover a utilização de frotas de veículos menos poluentes (Euro 5 e Euro 6) e a introdução de veículos elétricos.', 'DO', 12, 143),
('104', 'Promover a formação profissional de trabalhadores para áreas de apoio ao Data Center, com vista a sua integração futura na equipa da START Campus e/ou empresas fornecedoras associadas ao Data Center, através da criação de parcerias com escolas da região ou dando continuidade a projetos já em desenvolvimento, nomeadamente o Projeto CEDCE - parceria com a Escola Tecnológica do Litoral Alentejano, com vista a formação de técnicos para o suporte e manutenção de Data Centers.', 'DO', 12, 144),
('105', 'Promover junto das instituições de ensino universitário da região a adequação dos cursos universitários existentes ou criação de especializações em áreas de necessidade do Data Center, com vista a formar recursos humanos para a START Campus e outras empresas fornecedoras de serviços', 'DO', 12, 145),
('106', 'Colocar sinalização no acesso a instalação industrial, adequada a circulação de veículos pesados e a moderação da velocidade de circulação, devendo respeitar as normas de segurança, nomeadamente a redução da velocidade de circulação junto das povoações.', 'DO | EE', 12, 146),
('107', 'Fornecer aos empreiteiros e subempreiteiros a Planta de Condicionamentos atualizada com a implantação de todos os elementos patrimoniais identificados, quer no EIA e no RECAPE, quer com os que se venham a identificar na fase de construção, sempre que se desenvolverem ações de manutenção ou outros trabalhos.', 'DO', 12, 147),
('108', 'Sempre que ocorram trabalhos de manutenção, que envolvam alterações que obriguem a revolvimentos do subsolo, circulação de maquinaria e pessoal afeto, nomeadamente em áreas anteriormente não afetadas pela construção das infraestruturas (e que não foram alvo de intervenção}, deve efetuar-se o acompanhamento arqueológico destes trabalhos e cumpridas as medidas de minimização previstas para a fase de construção, quando aplicáveis.', 'DO | EE', 12, 148),
('109', 'Caso se verifique a execução de ações de limpeza ou desassoreamento, deve ser solicitado um parecer da Tutela do Património Cultural de forma a salvaguarda esses valores e onde podem ser definidas eventuais medidas de minimização, nomeadamente o acompanhamento arqueológico por uma equipa de arqueologia com experiência comprovada na vertente náutica e subaquática, previamente autorizada, e que esteja dimensionada em relação a dinâmica e volume de trabalhos a realizar.', 'DO | EE', 12, 149),
('110', 'Caso a manutenção da faixa de proteção da linha ou da faixa de gestão de combustível, implique o abate ou afetação de sobreiros ou azinheiras, esta ação deve ser comunicada ao ICNF e deve existir compensação, com os mesmos valores que se encontram definidos no Projeto de Compensação pelo abate e afetação de sobreiros.', 'DO | EE', 12, 150),
('111', 'Tendo em conta o horizonte de tempo de vida útil previsto para o projeto, e a dificuldade de prever as condições ambientais locais e os instrumentos de gestão territorial e legais que irão estar em vigor, deve o promotor, no último ano de exploração do projeto, apresentar a solução futura de ocupação da área de implantação do projeto, após a respetiva desativação. Se a alternativa passar pela desativação, deve ser apresentado um plano pormenorizado, contemplando nomeadamente:', 'DO | EE', 14, 151),
('111.1', 'A solução final de requalificação da área de implantação do Data Center, Subestação e das Linhas elétricas associadas, a qual deve ser compatível com o direito de propriedade, os instrumentos de gestão territorial e com o quadro legal então em vigor.', 'DO | EE', 14, 152),
('111.2', 'Ações de desmantelamento e obra.', 'DO | EE', 14, 153),
('111.3', 'Destino a dar a todos os elementos retirados.', 'DO | EE', 14, 154),
('111.4', 'Definição das soluções de acessos ou outros elementos a permanecer no terreno.', 'DO | EE', 14, 155),
('111.5', 'Plano de recuperação final de todas as áreas afetadas.', 'DO | EE', 14, 156);